const p = msg.payload || {};
const id = String(p.audio_id || Date.now()).replace(/[^a-zA-Z0-9_-]/g,'').slice(0,48) || String(Date.now());
const b64 = String(p.audio_base64 || '');
if (!b64) {
  msg.statusCode = 400;
  msg.payload = {ok:false, accepted:false, error:'audio_base64_required'};
  return [null, msg];
}
let buf;
try { buf = Buffer.from(b64, 'base64'); } catch (e) { buf = null; }
if (!buf || !buf.length) {
  msg.statusCode = 400;
  msg.payload = {ok:false, accepted:false, error:'audio_decode_failed'};
  return [null, msg];
}
const filename = `/tmp/recamera_voice_${id}.wav`;
flow.set('rcAudioState', {ok:true, state:'saving', audio_id:id, filename, updated_at:Date.now(), last_error:''});
const fileMsg = RED.util.cloneMessage(msg);
fileMsg.filename = filename;
fileMsg.audio_id = id;
fileMsg.payload = buf;
const res = RED.util.cloneMessage(msg);
res.statusCode = 202;
res.payload = {ok:true, accepted:true, state:'saving', audio_id:id, filename};
return [fileMsg, res];

const id = String(msg.audio_id || '');
const filename = String(msg.filename || '');
flow.set('rcAudioState', {ok:true, state:'playing', audio_id:id, filename, updated_at:Date.now(), last_error:''});
msg.payload = filename;
return msg;

const rc = Number(msg.payload && msg.payload.code !== undefined ? msg.payload.code : msg.rc && msg.rc.code !== undefined ? msg.rc.code : msg.payload || 0);
const prev = flow.get('rcAudioState') || {};
const ok = rc === 0;
flow.set('rcAudioState', {...prev, ok, state: ok ? 'done' : 'error', exit_code: rc, updated_at:Date.now(), last_error: ok ? '' : 'aplay_failed'});
return null;

const st = flow.get('rcAudioState') || {ok:true, state:'idle', audio_id:'', filename:'', updated_at:0, last_error:''};
msg.payload = st;
return msg;

const prev = flow.get('rcAudioState') || {};
flow.set('rcAudioState', {...prev, ok:true, state:'stopped', updated_at:Date.now(), last_error:''});
const res = RED.util.cloneMessage(msg);
res.payload = {ok:true, state:'stopped'};
msg.payload = '';
return [msg, res];
